package httpapi

import (
	"io"
	"net/http"

	"github.com/mmhk/svn-admin/pkg/docs"
)

// openapiJSON serves the Swagger 2.0 document generated by swag. The UI is
// configured with the relative URL "openapi.json" so it also works behind the
// /svnadmin/api/docs/ prefix.
func (a *API) openapiJSON(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", contentTypeJSON)
	w.WriteHeader(http.StatusOK)

	_, _ = io.WriteString(w, docs.SwaggerInfo.ReadDoc())
}
